#include <stdio.h>
#include <string.h>

/* The contract promises at most 15 characters plus a terminator. */
#define ROMAN_MAX 16

/* Provided by the candidate in solution.c */
void to_roman(int value, char *out);

int main(void)
{
    int value;

    while (scanf("%d", &value) == 1) {
        /* Four times the promised room, prefilled with a byte that is not a
         * Roman symbol, so a missing terminator is caught and reported here
         * rather than printing whatever happened to follow. */
        char buffer[ROMAN_MAX * 4];
        memset(buffer, '?', sizeof buffer);

        to_roman(value, buffer);

        if (memchr(buffer, '\0', ROMAN_MAX) == NULL) {
            printf("UNTERMINATED (no '\\0' in the first %d bytes)\n",
                   ROMAN_MAX);
            return 1;
        }
        printf("%s\n", buffer);
    }
    return 0;
}
